// TreeExpander — Gtk.TreeExpander
//
// Generated by bin/11-generate-components, which does not overwrite.
//
// It ships no template, so the markup is the one element its CSS node is, carrying what
  // Adwaita styles treeexpander with.

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"
import type { WidgetProps } from "@/lib/widget-props"

export interface TreeExpanderProps extends WidgetProps {
  className?: string
  children?: ReactNode
  /** Widget, from Gtk.TreeExpander */
  child?: ReactNode

  /** gboolean, from Gtk.TreeExpander */
  hideExpander?: boolean

  /** gboolean, from Gtk.TreeExpander */
  indentForDepth?: boolean

  /** gboolean, from Gtk.TreeExpander */
  indentForIcon?: boolean

  /** TreeListRow, from Gtk.TreeExpander */
  listRow?: ReactNode
}

export function TreeExpander({ className, children }: TreeExpanderProps) {
  return (
    <div className={cn("gap-[4px]", className)}>
      {children}
    </div>
  )
}
